   public HttpResponse doScan(StaplerRequest incomingReq) throws IOException, GeneralSecurityException {
       if(incomingReq.hasParameter("background")) {
           start(false);
       } else
       if(incomingReq.hasParameter("schedule")) {
           scanOnBoot.on();
       } else
       if(incomingReq.hasParameter("dismiss")) {
           disable(true);
       } else
           throw HttpResponses.error(400,"Invalid request submission: " + incomingReq.getParameterMap());

       return HttpResponses.redirectViaContextPath("/manage");
   }

