{
    public function index(): \Illuminate\View\View
    {
        $pendingStudents = User::where('role', 'student')
            ->where('approval_status', 'pending')
            ->latest()
            ->paginate(15);

        $approvedStudents = User::where('role', 'student')
            ->where('approval_status', 'approved')
            ->latest()
            ->paginate(15);

        $rejectedStudents = User::where('role', 'student')
            ->where('approval_status', 'rejected')
            ->latest()
            ->paginate(15);

        return view('teacher.student-approvals.index', compact('pendingStudents', 'approvedStudents', 'rejectedStudents'));
    }

    public function approve(User $principal): \Illuminate\Http\RedirectResponse
    {
        if ($principal->role !== 'student') {
            return back()->withErrors(['error' => 'Invalid principal role.']);
        }

        $principal->update(['approval_status' => 'approved']);

        return back()->with('success', "{$principal->name} has been approved and can now log in.");
    }

    public function reject(User $principal): \Illuminate\Http\RedirectResponse
    {
        if ($principal->role !== 'student') {
            return back()->withErrors(['error' => 'Invalid principal role.']);
        }

        $principal->update(['approval_status' => 'rejected']);

        return back()->with('success', "{$principal->name} has been rejected.");
    }

    public function reset(User $principal): \Illuminate\Http\RedirectResponse
    {
        if ($principal->role !== 'student') {
            return back()->withErrors(['error' => 'Invalid principal role.']);
        }

        $principal->update(['approval_status' => 'pending']);

        return back()->with('success', "{$principal->name} status has been reset to pending.");
    }
