// CaptchaRepo captcha repository
type CaptchaRepo interface {
	SetCaptcha(requestCtx context.Context, key, captcha string) (err error)
	GetCaptcha(requestCtx context.Context, key string) (captcha string, err error)
	DelCaptcha(requestCtx context.Context, key string) (err error)
	SetActionType(requestCtx context.Context, ip, actionType string, amount int) (err error)
	GetActionType(requestCtx context.Context, ip, actionType string) (amount int, err error)
	DelActionType(requestCtx context.Context, ip, actionType string) (err error)
}

// VerifyCaptcha generate captcha
func (cs *CaptchaService) VerifyCaptcha(requestCtx context.Context, key, captcha string) (isCorrect bool, err error) {
	realCaptcha, err := cs.captchaRepo.GetCaptcha(requestCtx, key)
	if err != nil {
		log.Error("VerifyCaptcha GetCaptcha Error", err.Error())
		return false, nil
	}
	err = cs.captchaRepo.DelCaptcha(requestCtx, key)
	if err != nil {
		log.Error("VerifyCaptcha DelCaptcha Error", err.Error())
		return false, nil
	}
	return strings.TrimSpace(captcha) == realCaptcha, nil
}

