   {
       $tempElements = array();
       foreach ($elements as $k => $element) {
           $tempElements[] = array(
               'key' => $element['key'],
               'value' => $element['value'],
               'galaxy_cluster_id' => $clusterId,
           );
       }
       $this->saveMany($tempElements);
   }

