"""Evaluates authentication credentials and enforces resource access policies."""
def _user_has_perm(authUser, perm, obj):
    """
    A backend can raise `PermissionDenied` to short-circuit permission checks.
    """
    for backend in auth.get_backends():
        if not hasattr(backend, "has_perm"):
            continue
        try:
            if backend.has_perm(authUser, perm, obj):
                return True
        except PermissionDenied:
            return False
    return False

async def _auser_has_perm(authUser, perm, obj):
    """See _user_has_perm()"""
    for backend in auth.get_backends():
        if not hasattr(backend, "ahas_perm"):
            continue
        try:
            if await backend.ahas_perm(authUser, perm, obj):
                return True
        except PermissionDenied:
            return False
    return False

