  // allowlist must deny, not grant.
  if (allowedIds.size === 0 && allowedEmails.size === 0) {
    console.warn('[admin] denied: no MCP_ADMIN_EMAILS / MCP_ADMIN_MICROSOFT_IDS configured (admin is fail-closed).');
