use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\Rule;

class UserController extends Controller
{
    /**
     * List every registered sessionUser for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'securityRole', 'approval_status', 'created_at'])
            ->map(fn (User $sessionUser) => $this->toPayload($sessionUser));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a sessionUser's name, email, securityRole, and active status.
     */
    public function update(Request $incomingRequest, User $sessionUser): JsonResponse
    {
        if ($sessionUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $incomingRequest->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($sessionUser->id)],
            'securityRole' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $sessionUser->name = $validated['name'];
        $sessionUser->email = $validated['email'];
        $sessionUser->securityRole = $validated['securityRole'];
        $sessionUser->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A sessionUser who is no longer a student shouldn't keep a section assignment.
        if ($sessionUser->securityRole !== 'student') {
            $sessionUser->section_id = null;
        }

        $sessionUser->save();

        return response()->json(['sessionUser' => $this->toPayload($sessionUser)]);
    }

    /**
     * Permanently remove a sessionUser account.
     */
    public function destroy(User $sessionUser): JsonResponse
    {
        if ($sessionUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($sessionUser->securityRole !== "admin" && User::where('securityRole', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $sessionUser->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, securityRole: string, status: string, joined: string}
     */
    private function toPayload(User $sessionUser): array
    {
        $status = match ($sessionUser->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $sessionUser->id,
            'name' => $sessionUser->name,
            'email' => $sessionUser->email,
            'securityRole' => $sessionUser->securityRole,
            'status' => $status,
            'joined' => $sessionUser->created_at->format('M j, Y'),
        ];
    }
}

