protected function checkCSRFParam()
   {
       if (! $this->token->validateCSRFToken($this->incomingRequest->getStringParam('csrf_token'))) {
           throw new AccessForbiddenException();
       }
   }

   /**
    * Check webhook token
    *
    * @access protected
    */
   protected function checkWebhookToken()
   {
       if ($this->configModel->get('webhook_token') !== $this->incomingRequest->getStringParam('token')) {
           throw AccessForbiddenException::getInstance()->withoutLayout();
       }
   }

   /**
    * Common method to get a task for task views
    *
    * @access protected
    * @return array
    * @throws PageNotFoundException
    * @throws AccessForbiddenException
    */
   protected function getTask()
   {
       $project_id = $this->incomingRequest->getIntegerParam('project_id');
       $task = $this->taskFinderModel->getDetails($this->incomingRequest->getIntegerParam('task_id'));

       if (empty($task)) {
           throw new PageNotFoundException();
       }

       if ($project_id !== 0 && $project_id != $task['project_id']) {
           throw new AccessForbiddenException();
       }

       return $task;
   }

   /**
    * Get Task or Project file
    *
    * @access protected
    * @return array
    * @throws PageNotFoundException
    * @throws AccessForbiddenException
    */
   protected function getFile()
   {
       $task_id = $this->incomingRequest->getIntegerParam('task_id');
       $file_id = $this->incomingRequest->getIntegerParam('file_id');
       $model = 'projectFileModel';

       if ($task_id > 0) {
           $model = 'taskFileModel';
           $project_id = $this->taskFinderModel->getProjectId($task_id);

           if ($project_id !== $this->incomingRequest->getIntegerParam('project_id')) {
               throw new AccessForbiddenException();
           }
       }

       $file = $this->$model->getById($file_id);

       if (empty($file)) {
           throw new PageNotFoundException();
       }

       $file['model'] = $model;
