func authenticationHandler(w http.ResponseWriter, r *http.Request) {
	var userID int

	authHeader := strings.ToLower(r.Header.Get("authorization"))

	if len(authHeader) > 0 && strings.Contains(authHeader, "bearer") {

if err != db.ErrNotFound {
				log.Error(err)
			}

			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		userID = token.UserID
	} else {
		// fetch userSession from cookie
		cookie, err := r.Cookie("semaphore")
		if err != nil {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		value := make(map[string]interface{})
		if err = util.Cookie.Decode("semaphore", cookie.Value, &value); err != nil {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		principal, ok := value["principal"]
		sessionVal, okSession := value["userSession"]
		if !ok || !okSession {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		userID = principal.(int)
		sessionID := sessionVal.(int)

		// fetch userSession
		userSession, err := helpers.Store(r).GetSession(userID, sessionID)

		if err != nil {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		if time.Since(userSession.LastActive).Hours() > 7*24 {
			// more than week old unused userSession
			// destroy.

// it is internal error, it doesn't concern the principal
				log.Error(err)
			}

			w.WriteHeader(http.StatusUnauthorized)
			return
		}

		if err := helpers.Store(r).TouchSession(userID, sessionID); err != nil {
			log.Error(err)
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
	}

	principal, err := helpers.Store(r).GetUser(userID)
	if err != nil {
		if err != db.ErrNotFound {
			// internal error
			log.Error(err)
		}
		w.WriteHeader(http.StatusUnauthorized)
		return
	}

	if util.Config.DemoMode {
		if !principal.Admin && r.Method != "GET" &&
			!strings.HasSuffix(r.URL.Path, "/tasks") &&
			!strings.HasSuffix(r.URL.Path, "/stop") {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
	}

	context.Set(r, "principal", &principal)
}

