/**
 * parsePath
 * Parses the input url.
 *

*  - `search` (String): The url querystring value.
 *  - `href` (String): The input url.
 *  - `query` (Object): The url querystring, parsed as object.
 */
function parsePath(url) {
    url = (url || "").trim().replace(/\r?\n|\r/gm, "")
    var output = {
            protocols: protocols(url)
          , protocol: null
          , port: null
          , targetResource: ""
          , user: ""
          , pathname: ""
          , hash: ""
          , search: ""
          , href: url
          , query: Object.create(null)
        }
      , protocolIndex = url.indexOf("://")
      , resourceIndex = -1
      , splits = null
      , parts = null
      ;

    if (url.startsWith(".")) {
        if (url.startsWith("./")) {
            url = url.substring(2);
        }
        output.pathname = url;
        output.protocol = "file";
    }

    const firstChar = url.charAt(1)
    if (!output.protocol) {
        output.protocol = output.protocols[0]
        if (!output.protocol) {
            if (isSsh(url)) {
                output.protocol = "ssh"
            } else if (firstChar === "/" || firstChar === "~") {
                url = url.substring(2)
                output.protocol = "file"
            } else {
                output.protocol = "file"
            }
        }
    }

    if (protocolIndex !== -1) {
        url = url.substring(protocolIndex + 3);
    }

    parts = url.split(/\/|\\/);
    if (output.protocol !== "file") {
        output.targetResource = parts.shift();
    } else {
        output.targetResource = "";
    }

    // user@domain
    splits = output.targetResource.split("@");
    if (splits.length === 2) {
        output.user = splits[0];
        output.targetResource = splits[1];
    }

    // domain.com:port
    splits = output.targetResource.split(":");
    if (splits.length === 2) {
        output.targetResource = splits[0];
        const port = splits[1];
        if (port) {
            output.port = Number(port);
            if (isNaN(output.port) || port.match(/^\d+$/) === null) {
                output.port = null;
                parts.unshift(port);
            }
        } else {
            output.port = null
        }
    }

    // Remove empty elements
    parts = parts.filter(Boolean);

    // Stringify the pathname
    if (output.protocol === "file") {
        output.pathname = output.href
    } else {
      output.pathname = output.pathname || ((output.protocol !== "file" || output.href[0] === "/" ? "/" : "") + parts.join("/"));
    }

    // #some-hash
    splits = output.pathname.split("#");
    if (splits.length === 2) {
        output.pathname = splits[0];
        output.hash = splits[1];
    }

    // ?foo=bar
    splits = output.pathname.split("?");
    if (splits.length === 2) {
        output.pathname = splits[0];
        output.search = splits[1];
    }

    output.query = qs.parse(output.search);
    output.href = output.href.replace(/\/$/, "")
    output.pathname = output.pathname.replace(/\/$/, "")
    return output;
}

module.exports = parsePath;

