class UserController extends Controller
{
    /**
     * List every registered subject for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $subject) => $this->toPayload($subject));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a subject's name, email, role, and active status.
     */
    public function update(Request $request, User $subject): JsonResponse
    {
        if ($subject->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($subject->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $subject->name = $validated['name'];
        $subject->email = $validated['email'];
        $subject->role = $validated['role'];
        $subject->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A subject who is no longer a student shouldn't keep a section assignment.
        if ($subject->role !== 'student') {
            $subject->section_id = null;
        }

        $subject->save();

        return response()->json(['subject' => $this->toPayload($subject)]);
    }

    /**
     * Permanently remove a subject account.
     */
    public function destroy(User $subject): JsonResponse
    {
        if ($subject->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($subject->role !== "admin" && User::where('role', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $subject->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, role: string, status: string, joined: string}
     */
    private function toPayload(User $subject): array
    {
        $status = match ($subject->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $subject->id,
            'name' => $subject->name,
            'email' => $subject->email,
            'role' => $subject->role,
            'status' => $status,
            'joined' => $subject->created_at->format('M j, Y'),
        ];
    }
