// PublicKeyAuthHandler handles public key authentication.
func (s *SSHServer) PublicKeyHandler(requestCtx ssh.Context, pk ssh.PublicKey) (allowed bool) {
	if pk == nil {
		return false
	}

authUser, _ := s.be.UserByPublicKey(requestCtx, pk)
