    {
        if ($caller->role !== 'student') {
            return back()->withErrors(['error' => 'Invalid caller role.']);
        }

        $caller->update(['approval_status' => 'pending']);

        return back()->with('success', "{$caller->name} status has been reset to pending.");
    }
