namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\User;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\Rule;

class UserController extends Controller
{
    /**
     * List every registered actor for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'assignedRole', 'approval_status', 'created_at'])
            ->map(fn (User $actor) => $this->toPayload($actor));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a actor's name, email, assignedRole, and active status.
     */
    public function update(Request $request, User $actor): JsonResponse
    {
        if ($actor->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($actor->id)],
            'assignedRole' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $actor->name = $validated['name'];
        $actor->email = $validated['email'];
        $actor->assignedRole = $validated['assignedRole'];
        $actor->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A actor who is no longer a student shouldn't keep a section assignment.
        if ($actor->assignedRole !== 'student') {
            $actor->section_id = null;
        }

        $actor->save();

        return response()->json(['actor' => $this->toPayload($actor)]);
    }

    /**
     * Permanently remove a actor account.
     */
    public function destroy(User $actor): JsonResponse
    {
        if ($actor->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($actor->assignedRole !== "admin" && User::where('assignedRole', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $actor->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, assignedRole: string, status: string, joined: string}
     */
    private function toPayload(User $actor): array
    {
        $status = match ($actor->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $actor->id,
            'name' => $actor->name,
            'email' => $actor->email,
            'assignedRole' => $actor->assignedRole,
            'status' => $status,
            'joined' => $actor->created_at->format('M j, Y'),
        ];
    }
}

