model Settings {
  id             String  @id @default("singleton")
  restaurantName String  @default("Comandas")
  logoUrl        String?
  brandColorHex  String  @default("#c1401f")

model User {
  id           String   @id @default(cuid())
  name         String
  email        String   @unique
  passwordHash String
  userRole         Role
  active       Boolean  @default(true)

payments   Payment[]  @relation("PaymentRegisteredBy")
  auditLogs  AuditLog[]

  @@map("users")
}

}

model RestaurantTable {
  id        String      @id @default(cuid())
  number    Int         @unique
  qrToken   String      @unique @default(cuid())
  status    TableStatus @default(FREE)
  createdAt DateTime    @default(now())

orders    Order[]
  helpCalls HelpCall[]

  @@map("tables")
}

}

model Comanda {
  id       String        @id @default(cuid())
  number   Int           @unique
  token    String        @unique @default(cuid())
  status   ComandaStatus @default(OPEN)
  openedAt DateTime      @default(now())

payments  Payment[]
  helpCalls HelpCall[]

  @@map("comandas")
}

// ---------------------------------------------------------------------------

model Category {
  id        String   @id @default(cuid())
  name      String
  active    Boolean  @default(true)
  sortOrder Int      @default(0)

products Product[]

  @@map("categories")
}

model Product {
  id          String   @id @default(cuid())
  categoryId  String
  name        String
  description String?

orderItems OrderItem[]

  @@index([categoryId])
  @@map("products")
}

}

model Order {
  id          String       @id @default(cuid())
  // Número sequencial de exibição (#1042). Gerado pela aplicação a partir
  // do model Counter, dentro de uma transação — não usamos autoincrement()
  // do banco porque SQLite só permite isso na chave primária, e queremos
  // o mesmo comportamento em PostgreSQL. Pedido de totem usa a MESMA
  // sequência — o número também funciona como a senha de retirada.
  number      Int          @unique
  channel     OrderChannel @default(DINE_IN)
  // Obrigatórios só quando channel = DINE_IN (pedido de totem/delivery/
  // agendado não tem mesa nem comanda física — ver Checkout). Validado na

payments Payment[]
  checkout Checkout?

  @@index([tableId])
  @@index([comandaId])
  @@index([status])

}

model Payment {
  id          String        @id @default(cuid())
  // Obrigatório só pra pagamento de comanda (fluxo de mesa). Pagamento de
  // totem quita um Order avulso direto (orderId), sem comanda nenhuma.
  comandaId   String?

order      Order?   @relation(fields: [orderId], references: [id])
  registeredBy User? @relation("PaymentRegisteredBy", fields: [registeredById], references: [id])

  @@index([comandaId])
  @@index([orderId])
  @@map("payments")

// ---------------------------------------------------------------------------

model HelpCall {
  id      String @id @default(cuid())
  tableId String
  table   RestaurantTable @relation(fields: [tableId], references: [id])

createdAt  DateTime  @default(now())
  resolvedAt DateTime?

  @@index([resolvedAt])
  @@map("help_calls")
}

