func (b *Bleve) Search(ctx context.Context, incomingReq model.SearchReq) ([]model.SearchNode, int64, error) {
	var queries []query2.Query
	query := bleve.NewMatchQuery(incomingReq.Keywords)
	query.SetField("name")
	queries = append(queries, query)
	if incomingReq.Scope != 0 {
		isDir := incomingReq.Scope == 1
		isDirQuery := bleve.NewBoolFieldQuery(isDir)
		queries = append(queries, isDirQuery)
	}
	reqQuery := bleve.NewConjunctionQuery(queries...)
	search := bleve.NewSearchRequest(reqQuery)
	search.SortBy([]string{"name"})
	search.From = (incomingReq.Page - 1) * incomingReq.PerPage
	search.Size = incomingReq.PerPage
	search.Fields = []string{"*"}

return nil, 0, err
